//! Goldens were generated by the independently compiled frozen original,
//! before comparing to this Rust implementation. See fixtures/t10/PROVENANCE.md.

use llama_behavior::{
    chat,
    grammar::Grammar,
    json,
    sampling::{Candidates, Config, Sampler},
};

#[test]
fn native_chat_540_original_output_transcripts() {
    let fixture = include_str!("../../../fixtures/t10/chat-reference.jsonl");
    let mut count = 0;
    for line in fixture.lines() {
        let v = json::parse(line).unwrap();
        let template = v.get("template").unwrap().as_str().unwrap();
        let messages = v
            .get("messages")
            .unwrap()
            .as_array()
            .unwrap()
            .iter()
            .map(|m| {
                chat::Message::new(
                    m.get("role").unwrap().as_str().unwrap(),
                    m.get("content").unwrap().as_str().unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let rendered = chat::render(
            template,
            &messages,
            v.get("add_assistant").unwrap().as_bool().unwrap(),
        )
        .unwrap();
        assert_eq!(
            rendered,
            v.get("expected").unwrap().as_str().unwrap(),
            "template {template} case {:?}",
            v.get("case")
        );
        count += 1;
    }
    assert_eq!(count, 540);
}

fn float(v: &json::Value) -> f32 {
    if v.as_str() == Some("-inf") {
        f32::NEG_INFINITY
    } else {
        v.as_f64().unwrap() as f32
    }
}
fn close(a: f32, b: f32) -> bool {
    a == b || (a - b).abs() <= 3e-6f32.max(b.abs() * 3e-6)
}

#[test]
fn sampler_256_original_apply_and_accept_steps() {
    let fixture = include_str!("../../../fixtures/t10/sampling-reference.jsonl");
    let mut count = 0;
    for line in fixture.lines() {
        let v = json::parse(line).unwrap();
        let config = Config::from_json(v.get("config").unwrap()).unwrap();
        let mut sampler = Sampler::new(config.clone()).unwrap();
        for token in v.get("history").unwrap().as_array().unwrap() {
            sampler.accept(token.as_i64().unwrap() as i32).unwrap();
        }
        for (step, s) in v
            .get("steps")
            .unwrap()
            .as_array()
            .unwrap()
            .iter()
            .enumerate()
        {
            let logits = s
                .get("logits")
                .unwrap()
                .as_array()
                .unwrap()
                .iter()
                .map(float)
                .collect::<Vec<_>>();
            let mut c = Candidates::from_logits(&logits).unwrap();
            sampler.apply(&mut c).unwrap();
            let values = s.get("values").unwrap().as_array().unwrap();
            assert_eq!(c.data.len(), values.len(), "{config:?} step {step}");
            assert_eq!(
                c.selected.map(|i| i as i64).unwrap_or(-1),
                s.get("selected").unwrap().as_i64().unwrap(),
                "{config:?} step {step}"
            );
            for (t, v) in c.data.iter().zip(values) {
                assert_eq!(
                    t.id,
                    v.get("id").unwrap().as_i64().unwrap() as i32,
                    "{config:?} step {step}"
                );
                let expected = float(v.get("logit").unwrap());
                assert!(
                    close(t.logit, expected),
                    "{config:?} step {step} logit {} != {expected}",
                    t.logit
                );
                let expected = float(v.get("p").unwrap());
                assert!(
                    close(t.p, expected),
                    "{config:?} step {step} probability {} != {expected}",
                    t.p
                );
            }
            // Logit-bias deliberately clears a potentially stale sorted flag;
            // all fixtures start unsorted, so the source and Rust flags agree.
            assert_eq!(
                c.sorted,
                s.get("sorted").unwrap().as_bool().unwrap(),
                "{config:?} step {step}"
            );
            if let Some(token) = c.selected_token() {
                sampler.accept(token).unwrap();
            }
            count += 1;
        }
    }
    assert_eq!(count, 256);
}

#[test]
fn all_eight_bundled_grammar_data_files_compile() {
    for (name, source) in [
        (
            "arithmetic",
            include_str!("../../../fixtures/t10/grammars/arithmetic.gbnf"),
        ),
        ("c", include_str!("../../../fixtures/t10/grammars/c.gbnf")),
        (
            "chess",
            include_str!("../../../fixtures/t10/grammars/chess.gbnf"),
        ),
        (
            "english",
            include_str!("../../../fixtures/t10/grammars/english.gbnf"),
        ),
        (
            "japanese",
            include_str!("../../../fixtures/t10/grammars/japanese.gbnf"),
        ),
        (
            "json",
            include_str!("../../../fixtures/t10/grammars/json.gbnf"),
        ),
        (
            "json_arr",
            include_str!("../../../fixtures/t10/grammars/json_arr.gbnf"),
        ),
        (
            "list",
            include_str!("../../../fixtures/t10/grammars/list.gbnf"),
        ),
    ] {
        let grammar = Grammar::parse(source).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert!(grammar.rule_count() > 0);
    }
}

#[test]
fn original_bundled_json_and_arithmetic_grammar_membership() {
    let g = Grammar::parse(include_str!("../../../fixtures/t10/grammars/json.gbnf")).unwrap();
    for text in [
        "{}",
        r#"{"a":[true,false,null,-1.25e-2],"unicode":"世界"}"#,
        "{\n  \"x\": 42\n}",
    ] {
        assert!(g.matches(text).unwrap(), "{text}");
    }
    for text in ["[]", r#"{"a":01}"#, r#"{"a":1,}"#, r#"{"x":"\q"}"#] {
        assert!(!g.matches(text).unwrap(), "{text}");
    }
    let g = Grammar::parse(include_str!(
        "../../../fixtures/t10/grammars/arithmetic.gbnf"
    ))
    .unwrap();
    assert!(g.matches("x+2=3\n").unwrap());
    assert!(g.matches("(a+b)*3=12\n").unwrap());
    assert!(!g.matches("x+2=3").unwrap());
}

#[test]
fn grammar_232_original_prefix_and_completion_decisions() {
    let mut count = 0;
    for line in include_str!("../../../fixtures/t10/grammar-reference.jsonl").lines() {
        let v = json::parse(line).unwrap();
        let g = Grammar::parse(v.get("grammar").unwrap().as_str().unwrap()).unwrap();
        let text = v.get("text").unwrap().as_str().unwrap();
        let mut r = g.recognizer().unwrap();
        let prefix = r.accept_bytes(text.as_bytes()).unwrap();
        assert_eq!(
            prefix,
            v.get("prefix").unwrap().as_bool().unwrap(),
            "prefix case {:?} {text:?}",
            v.get("case")
        );
        assert_eq!(
            prefix && r.can_end(),
            v.get("complete").unwrap().as_bool().unwrap(),
            "complete case {:?} {text:?}",
            v.get("case")
        );
        count += 1;
    }
    assert_eq!(count, 232);
}
